import { HttpClient } from '@angular/common/http';
import { Component, OnInit, inject } from '@angular/core';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css']
})
export class DashboardComponent{
   http: HttpClient = inject(HttpClient)
  showCreateTaskForm: boolean = false;

  OpenCreateTaskForm(){
    this.showCreateTaskForm = true;
  }

  CloseCreateTaskForm(){
    this.showCreateTaskForm = false;
  }
  CreateOrUpdateTask(taskData: any){
    // console.log(taskData);
    this.http.post<name: string('https://angularhttpclient-bf6c9-default-rtdb.firebaseio.com/tasks.json', taskData).subscribe((response) => {
           console.log(response);
    });
  }
}
<app-create-task 
        *ngIf="showCreateTaskForm" 
        (CloseForm)="CloseCreateTaskForm()"
        (EmitTaskData)="CreateOrUpdateTask($event)"
></app-create-task>

<div class="dashboard-container">
    <div style="display: flex;">
        <div style="width: 50%">
            <h2>Dashboard</h2>
        </div>
        <div style="width: 50%; text-align: right;">
            <button class="create-task-btn" (click)="OpenCreateTaskForm()">Create Task</button>
            <button class="create-task-btn">Fetch Tasks</button>
            <button class="create-task-btn">Clear Tasks</button>
        </div>
    </div>

    <hr>

    <div class="dashboard-item-container">
            <div class="task-item">
                <div class="task-title">
                    <h3>Task Title</h3>
                </div>
                <p><b>Assigned to: </b>John Smith</p>
                <p><b>Priority: </b>High</p>
                <p><b>Status: </b>In Progress</p>
                <div class="task-action-icons">
                    <button class="task-action-btn" title="Detail">
                        <i class="fa fa-info-circle" aria-hidden="true"></i>
                    </button>
                    <button class="task-action-btn" title="Edit">
                        <i class="fa fa-pencil-square-o" aria-hidden="true"></i>
                    </button>
                    <button class="task-action-btn" title="Delete">
                        <i class="fa fa-trash" aria-hidden="true"></i>
                    </button>            
                </div>
            </div>
    </div>
</div>
